  /// <summary>
  /// Deal action
  /// </summary>
  public enum DealAction {
    /// <summary>
    /// A Buy deal
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_BUY")] Buy = 0,
    /// <summary>
    /// A Sell deal
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_SELL")] Sell = 1,
    /// <summary>
    /// A balance operation
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_BALANCE")] Balance = 2,
    /// <summary>
    /// Credit operation
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_CREDIT")] Credit = 3,
    /// <summary>
    /// Additional charges/withdrawals
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_CHARGE")] Charge = 4,
    /// <summary>
    /// Correcting operations
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_CORRECTION")] Correction = 5,
    /// <summary>
    /// Bonuses. Operations of this type affect the credit assets of a client
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_BONUS")] Bonus = 6,
    /// <summary>
    /// Commission
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_COMMISSION")] Commission = 7,
    /// <summary>
    /// Daily commission
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_COMMISSION_DAILY")] CommissionDaily = 8,
    /// <summary>
    /// Monthly commission
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_COMMISSION_MONTHLY")] CommissionMonthly = 9,
    /// <summary>
    /// Daily agent commission
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_AGENT_DAILY")] AgentDaily = 10,
    /// <summary>
    /// Monthly agent commission
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_AGENT_MONTHLY")] AgentMonthly = 11,
    /// <summary>
    /// Accrual of annual interest
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_INTEREST_RATE")] InterestRate = 12,
    /// <summary>
    /// A canceled Buy deal
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_BUY_CANCELED")] BuyCanceled = 13,
    /// <summary>
    /// A canceled Sell deal
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_SELL_CANCELED")] SellCanceled = 14,
    /// <summary>
    /// Dividend operations
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_DIVIDEND")] Dividend = 15,
    /// <summary>
    /// Franked (non-taxable) dividend operations (tax is paid by a company, not a client)
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_DIVIDEND_FRANKED")] DividendFranked = 16,
    /// <summary>
    /// Charging a tax
    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_TAX")] Tax = 17,
