    /// </summary>
    [pbr::OriginalName("DEAL_ACTION_SO_COMPENSATION_CREDIT")] SoCompensationCredit = 20,
  }

  /// <summary>
  /// Entry flag
  /// </summary>
  public enum EntryFlag {
    /// <summary>
    /// Entering the market or adding the volume
    /// </summary>
    [pbr::OriginalName("ENTRY_FLAG_IN")] In = 0,
    /// <summary>
    /// Exit from the market or partial closure
    /// </summary>
    [pbr::OriginalName("ENTRY_FLAG_OUT")] Out = 1,
    /// <summary>
    /// The deal that closed an existing position and opened a new one in the opposite direction. It is only used with the netting position accounting system.
    /// </summary>
    [pbr::OriginalName("ENTRY_FLAG_INOUT")] Inout = 2,
