    /// Close by : a simultaneous closure of two opposite positions of the same financial instrument. This operation type is only used in the hedging mode.
    /// </summary>
    [pbr::OriginalName("ENTRY_FLAG_OUT_BY")] OutBy = 3,
  }

  /// <summary>
  /// Deal reason
  /// </summary>
  public enum DealReason {
    /// <summary>
    /// The deal is conducted by a client manually through the client terminal
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_CLIENT")] Client = 0,
    /// <summary>
    /// The deal is conducted by a client using an Expert Advisor
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_EXPERT")] Expert = 1,
    /// <summary>
    /// The deal is conducted by a dealer through the manager terminal
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_DEALER")] Dealer = 2,
    /// <summary>
    /// The deal is conducted as a result of Stop Loss activation
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_SL")] Sl = 3,
    /// <summary>
    /// The deal is conducted as a result of Take Profit activation
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_TP")] Tp = 4,
    /// <summary>
    /// The deal is conducted when the client reached the Stop-Out level
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_SO")] So = 5,
    /// <summary>
    /// The deal is conducted when reopening a position for charging swaps
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_ROLLOVER")] Rollover = 6,
    /// <summary>
    /// The deal is conducted from an external trading system. As opposed to DEAL_REASON_EXTERNAL_SERVICE, commission is charged in this type of deal.
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_EXTERNAL_CLIENT")] ExternalClient = 7,
    /// <summary>
    /// The deal is conducted to charge the variation margin
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_VMARGIN")] Vmargin = 8,
    /// <summary>
    /// The deal is conducted by a MetaTrader 5 gateway connected to the platform
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_GATEWAY")] Gateway = 9,
    /// <summary>
    /// The deal is conducted as a result of copying a trading signal according to the subscription in the client terminal
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_SIGNAL")] Signal = 10,
    /// <summary>
    /// Forced closing of a position due to a futures/option delivery date coming into effect
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_SETTLEMENT")] Settlement = 11,
    /// <summary>
    /// The deal is conducted as a result of relocating a position with a calculated price to a new symbol with the same underlying asset
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_TRANSFER")] Transfer = 12,
    /// <summary>
    /// The deal is conducted while synchronizing a trading account with an external system
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_SYNC")] Sync = 13,
    /// <summary>
    /// Deal performed from an external trading system for technical reasons (for example, to correct the trade state of a client). Commission is not charged on this type of deals.
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_EXTERNAL_SERVICE")] ExternalService = 14,
    /// <summary>
    /// The deal is created while importing clients' trading operations from the MetaTrader 4 server
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_MIGRATION")] Migration = 15,
    /// <summary>
    /// The deal is conducted via the MetaTrader 5 mobile terminal for Android or iPhone
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_MOBILE")] Mobile = 16,
    /// <summary>
    /// The deal is conducted via the web terminal
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_WEB")] Web = 17,
    /// <summary>
    /// The deal is conducted as a result of a symbol split
    /// </summary>
    [pbr::OriginalName("DEAL_REASON_SPLIT")] Split = 18,
